   private int A;
   private int B;
   private int C;

   public Soccer(int x, int y, int z)
   {
     A = x;
     B = y;
     C = z;
   }

   public Soccer(int x, int y)
   {
     this(y, x, x+y);
   }

   public Soccer(int x)
   {
     this(x, 2*x);
   }

   public Soccer()
   {
     this(10);
   }

   public int primetime()
   {
    return A+B+C;
   }
}


